// Generated by `just generate` from `src/plugins/dotclaude/slices/asks/weak-limits.ts`. Edit the source and run `just generate`.
// The bounds and word lists of the ask on a weaker check (package P36), in one place.
// `limits.ts` exports them, so a user of the slice imports `limits.ts` only.
// A list is data and not a bound. Each regular expression runs on one line or one statement.

/** The most characters of one statement that the reader of code text scans. */
export const STATEMENT_MAX_CHARS = 4_000;

/** The most nested levels of a JSON value that the config check compares. A deeper value is a value that the check cannot read. */
export const JSON_DEPTH_MAX = 24;

/**
 * The text of an added line of a test file that is control flow, a skip, a focus, or a timeout.
 * The check runs on the line without the inside of its strings and without its comment.
 * A line like this can stop a test before its asserts, so that an added assert checks nothing.
 */
export const TEST_CONTROL = new RegExp(
  [
    String.raw`\b(?:if|else|elif|unless|when|return|try|catch|except|finally|switch|for|foreach|each|while|loop|break|continue|exit|and|or)\b`,
    String.raw`\b(?:skip\w*|only|todo|xfail|pending|ignore\w*|disabled?|should_panic|expectedFailure|cfg\w*)\b`,
    String.raw`(?<![.\w])(?:fit|xit|xtest|xdescribe|fdescribe)\b`,
    "timeout|_exit\\b|\\?|&&|\\|\\|",
    String.raw`^\}\s*,[^,]*\)\s*;?$`,
    String.raw`\}\s*,\s*\d[\d_.e]*\s*\)\s*;?$`,
  ].join("|"),
  "i",
);

/**
 * The calls in an added line of a test file that hide a test: a runtime skip, a mocked module, a global assignment, or an assert count of zero.
 * An added line with one of them asks in any position, also in a new test block.
 */
export const TEST_HIDING_CALL = new RegExp(
  [
    String.raw`\bpytest\.importorskip\s*\(`,
    String.raw`\bmock\.module\s*\(`,
    String.raw`\b(?:jest|vi)\.(?:mock|doMock|unstable_mockModule)\s*\(`,
    String.raw`\bmock\.patch\b`,
    String.raw`@(?:\w+\.)*patch\b`,
    String.raw`\bglobalThis\.\w+\s*=(?![=>])`,
    String.raw`\bexpect\.assertions\s*\(\s*0\s*\)`,
  ].join("|"),
);

/**
 * The forms of an import line that has a name list, as the key part and the names.
 * A line of one of these forms may add names (package P54).
 * Group 1 is the part before the names, group 2 is the names, and group 3 is the part after them.
 * A line with a default or namespace import, or with a `*`, has no such form.
 */
export const NAME_LIST_IMPORTS = [
  /^(import\s+(?:type\s+)?\{)([^{}]*)(\}\s*from\s*["'][^"']+["']\s*;?)$/,
  /^((?:const|let|var)\s*\{)([^{}]*)(\}\s*=\s*require\(\s*["'][^"']+["']\s*\)\s*;?)$/,
  /^(from\s+[\w.]+\s+import\s+\(?)([^()*]*)(\)?)$/,
];

/** The names that a test file uses as test globals. An import that adds one of them asks, because it can shadow the global. */
export const TEST_GLOBAL_NAMES = new Set([
  "expect",
  "test",
  "it",
  "describe",
  "assert",
  "beforeEach",
  "afterEach",
  "beforeAll",
  "afterAll",
  "vi",
  "jest",
  "mock",
  "pytest",
  "unittest",
  "TestCase",
  "skip",
  "patch",
]);

/** The form of one plain name in the name list of an import. */
export const PLAIN_NAME = /^[A-Za-z_$][\w$]*$/;

/** The joined multi-line forms of an import with a name list: the text is cut to one line before the check. */
export const MULTI_LINE_IMPORTS = [
  /^import\s+(?:type\s+)?\{[^{}]*\}\s*from/gm,
  /^(?:const|let|var)\s*\{[^{}]*\}\s*=\s*require/gm,
  /^from\s+[\w.]+\s+import\s*\([^()]*\)/gm,
];

/** The start of a Python assignment of a lambda. An added one at module level asks. */
export const PY_LAMBDA_ASSIGN = /^[A-Za-z_]\w*\s*=\s*lambda\b/;

/** The start of a test in a test file. The check counts the tests, so a removed test shows. */
export const TEST_DECLARATION = [
  /\b(?:test|it)(?:\.\w+)*\s*(?:\([^)]*\))?\s*\(\s*["'`]/,
  /^[ \t]*(?:async\s+)?def\s+test\w*/,
  /^func\s+Test\w+/,
  /#\[(?:\w+::)?test\b/,
  /@Test\b/,
  /^[ \t]*it\s+["']/,
];

/** The declarations of a bound in a limits file. The first group is the name. */
export const BOUND_DECLARATION = [
  /^[ \t]*(?:export\s+)?(?:const|let|var)\s+([A-Za-z_$][\w$]*)[^=\n]*=(?!=)/,
  /^[ \t]*(?:pub(?:\([a-z]+\))?\s+)?(?:const|static)\s+(\w+)[^=\n]*=(?!=)/,
  /^([A-Z_][A-Z0-9_]*)\s*(?::[^=\n]+)?=(?!=)/,
];

/** The extensions of a limits file that has code, where a bound is a declaration. */
export const BOUND_CODE_FILE = /\.(?:[cm]?[jt]sx?|py|rs|go|java|kt|swift|rb)$/;

/** The extensions of a file where `#` starts a comment. */
export const HASH_COMMENT_FILE =
  /\.(?:py|rb|sh|bash|toml|ya?ml|ini|cfg|conf)$|(?:^|\/)(?:Makefile|justfile)$/;

/** The rank of a level of a rule. A lower rank checks less. */
export const LEVEL_RANK: Record<string, number> = {
  error: 3,
  err: 3,
  deny: 3,
  forbid: 3,
  fatal: 3,
  warn: 2,
  warning: 2,
  info: 1,
  hint: 1,
  suggestion: 1,
  off: 0,
  none: 0,
  allow: 0,
  ignore: 0,
  disable: 0,
  disabled: 0,
};

/** The names of a key where a lower number checks less (a threshold of coverage). */
export const THRESHOLD_KEY =
  /coverage|threshold|fail[-_]?under|minimum|\bmin\b|(?:^|[-_.])min(?:[-_.]|$)|^(?:lines|branches|functions|statements|percent)$/i;

/** The names of a key whose list gets entries that switch off a check. A new entry checks less. */
export const IGNORE_KEY =
  /ignor|exclu|skip|omit|allow|disable|suppress|exempt|baseline|per-?file|noqa|unlisted|bypass/i;

/** The file extensions of a CI file that the YAML reader of `cidiff.ts` reads. Another CI file is compared as text. */
export const CI_YAML_FILE = /\.ya?ml$/i;

/** The keys of a CI step or job that skip it or let it fail. An added step or job with one of them asks. The text is one line of a key or of an inline map. */
export const CI_RISKY_KEY =
  /(?:^|[\s{,])["']?(?:if|continue-on-error|timeout-minutes|shell|allow_failure|when)["']?\s*:|<<\s*:/;

/** The text of a CI line that lets a command fail without a failed step. The text is one line of a `run` value or of a script. */
export const CI_RISKY_COMMAND = [
  /\|\|\s*(?:true\b|:(?:\s|$)|exit\s+0\b|echo\b)/,
  /;\s*(?:true\b|:(?:\s|$))/,
  /\bexit\s+0\b/,
  /\bset\s+\+e\b/,
  /^(?:true|:)$/,
  /^["']?run["']?\s*:\s*["']?(?:true["']?\s*$|:["']?\s*$|exit\b)/,
];

/** The parents of a CI line where an added child is safe: a step under `steps`, and a job under `jobs`. */
export const CI_ADDABLE_PARENT = /^["']?(?:steps|jobs)["']?:$/;

/** The key of a CI step that runs a command. An added part with this key at any depth asks. */
export const CI_RUN_KEY = /^["']?run["']?\s*:/;

/** The first word of a command in an added CI `run` that checks, builds, or installs. Only such a command is safe in an added step. */
export const CI_SAFE_PROGRAM =
  /^(?:(?:bun|bunx|npm|npx|pnpm|yarn|just|make|cargo|go|pytest|uv|tox|ruff|mypy|tsc|eslint|biome|pip|pip3|shellcheck|golangci-lint)|python3?\s+-m)(?=\s|$)/;

/** The text of a `run` line that writes a file or a CI variable file, such as a redirect, `tee`, or `$GITHUB_ENV`. */
export const CI_RUN_WRITE = />|\btee\b|GITHUB_(?:ENV|PATH|OUTPUT)\b/;

/** The key of a CI step that runs an action. An added step is safe only with this key. */
export const CI_USES_KEY = /^["']?uses["']?\s*:/;

/**
 * The text of an added line of a shell hook script that makes the script stricter: `set -e`, `set -u`, and `set -o pipefail`, in any mix.
 * Every other added line of a hook script asks, so this list is the only safe code line of a shell script.
 */
export const STRICT_SCRIPT_LINE =
  /^set(?: -[eu]+| -[eu]*o (?:pipefail|errexit|nounset)| -o (?:pipefail|errexit|nounset))+$/;

/** The text of an added `"use strict"` line of a JavaScript hook script. It is the only safe code line of such a script. */
export const USE_STRICT_LINE = /^(?:"use strict"|'use strict')\s*;?$/;

/** The path of a hook script that a shell runs, where the last command sets the exit status. A first line `#!` with a shell counts too. */
export const SHELL_SCRIPT =
  /\.(?:sh|bash|zsh)$|(?:^|\/)\.husky\/|(?:^|\/)[^./]+$/;

/** The first line of a script that a shell runs. */
export const SHELL_SHEBANG = /^#!.*\b(?:ba|z|da|k)?sh\b/;

/** The keys of `permissions` where a removed entry lets calls run with fewer asks. */
export const PERMISSION_DENY_KEYS = ["deny", "ask"];

/** The keys of `permissions` where an added entry lets calls run with fewer asks. */
export const PERMISSION_ALLOW_KEYS = ["allow", "additionalDirectories"];

/** The keys of a lint config or a type-check config where `true` is the strictest value. A new key with `true` checks more. */
export const STRICT_FLAG_KEY =
  /^(?:strict|recommended|noUnused\w+|noImplicit\w+|noFallthroughCasesInSwitch|noUncheckedIndexedAccess|noPropertyAccessFromIndexSignature|exactOptionalPropertyTypes|alwaysStrict|strict[A-Z]\w*|useUnknownInCatchVariables|forceConsistentCasingInFileNames|verbatimModuleSyntax|isolatedModules)$/;

/** The keys of a list where a new entry checks more files or more rules. */
export const GROWABLE_LIST_KEY =
  /^(?:select|extend-select|extendSelect|include|includes|enable|only)$/i;

/** The keys of a list that narrows the scope when the key is new, because a missing key means all. A new key of this kind asks. */
export const NARROWING_LIST_KEY = /^(?:select|include|includes|only)$/i;

/** The sections of `pyproject.toml` that hold a linter, type-check, test, security, or task config. A match on the section name asks. */
export const PYPROJECT_SECTIONS =
  /^tool\.(?:ruff|mypy|pytest|pyright|basedpyright|ty|pyrefly|black|pylint|isort|coverage|flake8|pycodestyle|pydocstyle|bandit|codespell|vulture|tox|nox|poe|pdm)(?:\.|$)|^tool\.hatch\.envs\.[^.]+\.scripts(?:\.|$)/;

/** The sections of `setup.cfg` that hold a linter, type-check, test, or security config. */
export const SETUP_CFG_SECTIONS =
  /^(?:flake8|mypy|pylint(?:\..+)?|pycodestyle|pydocstyle|isort|bandit|codespell|vulture|pyflakes|coverage(?::.+)?|tool:pytest|pytest)$/;

/** The start of an added line of a test file that asserts, such as `expect(`, `assert`, a Go `t.Errorf(`, or a `describe` block. */
export const TEST_SAFE_START =
  /^(?:await\s+)?(?:(?:self|this|t)\.)?(?:expect|assert\w*!?|should|describe|suite|context|Error|Errorf|Fatal|Fatalf)\s*\(|^assert\s/;

/** The end of an added test declaration that opens a block or a list, such as `{`, `:`, or `]` for a Rust attribute. */
export const TEST_OPEN_END = /[{:\]]\s*$/;

/** The entries of a list that take files or rules away. */
export const NEGATED_ENTRY = /^[!-]/;

/** The file names of a config in INI format that have no `.ini` or `.cfg` extension. */
export const INI_CONFIG_FILE =
  /\.(?:ini|cfg)$|^\.(?:flake8|pylintrc|coveragerc|shellcheckrc)$/;

/** The extension of a config in code, which the check reads as tokens. */
export const CODE_CONFIG_FILE = /\.[cm]?[jt]sx?$/;
